oxy_webhelp_navlinks = {"recover_okta_objects-d39307e60333":{"topics":[{"title":"Relationship restore scope","shortdesc":"<p class=\"shortdesc\">Granular recovery for Okta objects enables you to restore selected objects along with         their dependencies. <span class=\"ph\">RSC<\/span> provides options to recover selected objects,         interconnected objects, and their relationships. This feature enables you to re-establish         broken links and corrupted relationships, such as those between users and         groups.<\/p>","href":"okta\/relationship_restore_scope.html","attributes":{"data-id":"relationship_restore_scope"},"menu":{"hasChildren":false},"tocID":"relationship_restore_scope-d39307e60346","topics":[]},{"title":"Recreate objects and restore relationships","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enhances granular recovery of critical Okta objects by         discovering, displaying, and simplifying the complex, interlinked object structure and         dependencies in Okta. This enables you to precisely select and manage the recovery of         critical Okta objects and their associated dependencies.<\/p>","href":"okta\/recreate_objects_restore_relationships.html","attributes":{"data-id":"recreate_objects_restore_relationships"},"menu":{"hasChildren":false},"tocID":"recreate_objects_restore_relationships-d39307e60360","topics":[]},{"title":"Multi-valued data recovery rules","shortdesc":"<p class=\"shortdesc\">Information about how to handle conflicts for multi-valued data, both attributes and         relationships, during recovery. <span class=\"ph\">RSC<\/span> provides two options, overwrite or merge         values, enabling you to select the option that best meets your organizational requirements         for data consistency.<\/p>","href":"okta\/multivalued_data_recovery_rules.html","attributes":{"data-id":"multivalued_data_recovery_rules"},"menu":{"hasChildren":false},"tocID":"multivalued_data_recovery_rules-d39307e60373","topics":[]},{"title":"Authentication settings recovery for Okta objects","shortdesc":"<p class=\"shortdesc\">When you recover Okta Identity Providers or Applications, <span class=\"ph\">RSC<\/span>         restores the client secrets and public trust configuration that Okta exposes, so recovered         objects can authenticate without manual reconfiguration.<\/p>","href":"okta\/okta_authentication_settings_recovery.html","attributes":{"data-id":"okta_authentication_settings_recovery"},"menu":{"hasChildren":false},"tocID":"okta_authentication_settings_recovery-d39307e60387","topics":[]},{"title":"Considerations for recovering authorization servers","shortdesc":"<p class=\"shortdesc\">Information about the limitations and post-recovery steps to consider when you         recover an Okta authorization server, because Okta cannot back up or regenerate certain         configurations.<\/p>","href":"okta\/auth_server_recovery_considerations.html","attributes":{"data-id":"auth_server_recovery_considerations"},"menu":{"hasChildren":false},"tocID":"auth_server_recovery_considerations-d39307e60401","topics":[]},{"title":"Considerations for recovering Okta hooks","shortdesc":"<p class=\"shortdesc\">Information about backup and recovery behavior for Okta event hooks and inline hooks,         including limitations that require manual steps after recovery.<\/p>","href":"okta\/okta_hooks_recovery_considerations.html","attributes":{"data-id":"okta_hooks_recovery_considerations"},"menu":{"hasChildren":false},"tocID":"okta_hooks_recovery_considerations-d39307e60412","topics":[]},{"title":"Considerations for recovering Okta authenticators","shortdesc":"<p class=\"shortdesc\">Information about prerequisites for capturing authenticators in backups, limitations         for authenticators that hold secrets, and authenticator-specific behavior during         recovery.<\/p>","href":"okta\/okta_authenticator_recovery_considerations.html","attributes":{"data-id":"okta_authenticator_recovery_considerations"},"menu":{"hasChildren":false},"tocID":"okta_authenticator_recovery_considerations-d39307e60423","topics":[]},{"title":"Post-recovery steps for Okta hooks","shortdesc":"<p class=\"shortdesc\">Manual steps required after recovering Okta event hooks or inline hooks to restore         full functionality.<\/p>","href":"okta\/okta_hooks_recovery_post_req.html","attributes":{"data-id":"okta_hooks_recovery_post_req"},"menu":{"hasChildren":false},"tocID":"okta_hooks_recovery_post_req-d39307e60434","topics":[]},{"title":"User status recovery rules","shortdesc":"<p class=\"shortdesc\">Information about how <span class=\"ph\">RSC<\/span> recovers users that were in a Staged or         Locked Out status when the snapshot was taken. Okta does not support reverting user         statuses, so <span class=\"ph\">RSC<\/span> provides settings to control how it restores user         statuses.<\/p>","href":"okta\/user_status_recovery_rules.html","attributes":{"data-id":"user_status_recovery_rules"},"menu":{"hasChildren":false},"tocID":"user_status_recovery_rules-d39307e60445","topics":[]},{"title":"Okta group rules recovery","shortdesc":"<p class=\"shortdesc\">To recover a group rule, it is important to understand that an Okta group rule cannot         exist without its target groups. <span class=\"ph\">RSC<\/span> applies dependency-aware behavior when         recovering group rules.<\/p>","href":"okta\/okta_group_rules_recovery.html","attributes":{"data-id":"okta_group_rules_recovery"},"menu":{"hasChildren":false},"tocID":"okta_group_rules_recovery-d39307e60462","topics":[]},{"title":"Okta cross-tenant recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> cross-tenant recovery for Okta restores directory objects from a         source tenant snapshot to a different onboarded target tenant.<\/p>","href":"okta\/okta_cross_tenant_recovery.html","attributes":{"data-id":"okta_cross_tenant_recovery"},"menu":{"hasChildren":false},"tocID":"okta_cross_tenant_recovery-d39307e60477","next":"okta_cross_tenant_recovery-d39307e60477"},{"title":"Recovering Okta objects","shortdesc":"<p class=\"shortdesc\">Recover required Okta objects using automated or on-demand snapshots of your Okta         tenant when a critical object is accidentally deleted or changed.<\/p>","href":"okta\/recovering_okta_objects.html","attributes":{"data-id":"recovering_okta_objects"},"menu":{"hasChildren":false},"tocID":"recovering_okta_objects-d39307e60515","topics":[]},{"title":"Recovering Okta directory objects to a different tenant","shortdesc":"<p class=\"shortdesc\">Recover Okta directory objects from a source tenant snapshot to a different onboarded         target tenant.<\/p>","href":"okta\/recovering_okta_objects_cross_tenant.html","attributes":{"data-id":"recovering_okta_objects_cross_tenant"},"menu":{"hasChildren":false},"tocID":"recovering_okta_objects_cross_tenant-d39307e60526","topics":[]},{"title":"Recovering Okta workflows","shortdesc":"<p class=\"shortdesc\">Recover specific Okta workflow automations from a snapshot when workflows are         accidentally deleted, misconfigured, or corrupted.<\/p>","href":"okta\/recovering_okta_workflows.html","attributes":{"data-id":"recovering_okta_workflows"},"menu":{"hasChildren":false},"tocID":"recovering_okta_workflows-d39307e60537","topics":[]},{"title":"Okta application recovery requirements","shortdesc":"<p class=\"shortdesc\">Recovering an Okta application may require manual action to restore         credentials, certificates, and provisioning configuration that <span class=\"ph\">RSC<\/span> cannot         automatically recover.<\/p>","href":"okta\/okta_app_recovery_post_req.html","attributes":{"data-id":"okta_app_recovery_post_req"},"menu":{"hasChildren":false},"tocID":"okta_app_recovery_post_req-d39307e60548","topics":[]},{"title":"Okta identity provider recovery requirements","shortdesc":"<p class=\"shortdesc\">Recovering an Okta identity provider can require manual steps, such as re-entering a         credential or updating a certificate that <span class=\"ph\">RSC<\/span> cannot complete         automatically.<\/p>","href":"okta\/okta_idp_recovery_post_req.html","attributes":{"data-id":"okta_idp_recovery_post_req"},"menu":{"hasChildren":false},"tocID":"okta_idp_recovery_post_req-d39307e60562","topics":[]},{"title":"Okta authenticator post-recovery requirements","shortdesc":"<p class=\"shortdesc\">Information about failure scenarios, remediation steps, and post-recovery validation         checks for Okta authenticator recovery.<\/p>","href":"okta\/okta_authenticator_recovery_post_req.html","attributes":{"data-id":"okta_authenticator_recovery_post_req"},"menu":{"hasChildren":false},"tocID":"okta_authenticator_recovery_post_req-d39307e60576","topics":[]}]}};